// Which demo documents have a pre-rendered readout checked into public/audio.
// Generated by scripts/generate-demo-audio.mjs — keep the two in sync.
const RECORDED = new Set([
  "demo-1:am",
  "demo-2:am",
  "demo-3:am",
  "demo-4:am",
  "demo-1:en",
  "demo-2:en",
  "demo-3:en",
  "demo-4:en",
]);

/**
 * URL of the bundled readout for a demo document, or null when the device voice
 * must be used instead. Recordings sound natural and work with zero network
 * calls for the audio file itself (it ships with the app).
 */
export function demoAudioUrl(demoId?: string | null, lang?: string | null): string | null {
  if (!demoId || !lang) return null;
  const key = `${demoId}:${lang}`;
  if (!RECORDED.has(key)) return null;
  return `/audio/${demoId}-${lang}.mp3`;
}
